    fn test_const_fold_i64_add() {
        let code = vec![Instr::PushI64(3), Instr::PushI64(4), Instr::AddI64];
        let (optimized, _) = optimize(code);
        assert_eq!(optimized.len(), 1);
        assert!(matches!(optimized[0], Instr::PushI64(7)));
    }

